/**
 * The technical details of an error under its sentence (D102 (23), spec/02 §3.28, spec/07 §4.1): the word „Details“
 * ([SbMessages.errorDetails]) after the 16 dp chevron in a 48 dp target, closed at first; open, [details] (the
 * system's own message, never a second sentence) in the code role, breaking anywhere. TalkBack hears „Details,
 * eingeklappt“ / „ausgeklappt“. The caller lines it up under the sentence (SbPrimaryActionBar does).
 */
@Composable
fun SbErrorDetails(
    details: String,
    modifier: Modifier = Modifier,
    initiallyExpanded: Boolean = false,
) {
    SbErrorDetailsView(details, modifier, initiallyExpanded, 0, 0, null)
}

/**
 * [SbErrorDetails] in a scrolling area (CHECKS.md §87): opening scrolls to the text, so the chevron is not all that moves.
 * [below] px of the area's end lie under a pinned action, and [area] is the area's height, 0 when unknown. [focus] lets the action above lead here.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
internal fun SbErrorDetailsView(details: String, modifier: Modifier, initiallyExpanded: Boolean, below: Int, area: Int, focus: FocusRequester?) {
    val t = SebaroTheme.tokens
    val c = SebaroTheme.colors
    val m = sbMessages()
    var open by rememberSaveable { mutableStateOf(initiallyExpanded) }
    val interaction = remember { MutableInteractionSource() }
    val requester = remember { BringIntoViewRequester() }
    val whole = remember { mutableStateOf(IntSize.Zero) }
    val ring = with(LocalDensity.current) { 4.dp.toPx() }
    val scope = rememberCoroutineScope()
    val show = {
        scope.launch {
            withFrameNanos { }                        // the text is laid out after this frame
            val size = whole.value
            val wanted = size.height + below + ring
            // the whole part with room for the pinned action, or from its top as far as the area goes
            val height = if (area > 0) minOf(wanted, area - ring) else wanted
            requester.bringIntoView(Rect(-ring, -ring, size.width + ring, height))
        }
    }
    Column(modifier.onSizeChanged { whole.value = it }.bringIntoViewRequester(requester)) {
        Row(
            Modifier
                .then(if (focus != null) Modifier.focusRequester(focus) else Modifier)
                .sbFocusRing(interaction, t.radius.control)
                .onFocusEvent { if (it.isFocused && below > 0) show() }
                .heightIn(min = t.size.targetTouch)
                .toggleable(
                    value = open,
                    interactionSource = interaction,
                    indication = null,
                    role = Role.Button,
                    onValueChange = {
                        open = it
                        if (it) show()
                    },
                )
                .semantics { stateDescription = if (open) m.errorDetailsOpen else m.errorDetailsClosed },
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(t.space.s1),
        ) {
            Icon(
                SebaroIcons.Outline16.ChevronDown,
                contentDescription = null,
                tint = c.textMuted,
                modifier = Modifier.size(t.size.iconSm).rotate(if (open) 180f else 0f),
            )
            Text(m.errorDetails, style = SebaroTheme.typography.label, color = c.text)
        }
        if (open) {
            Text(
                details,
                style = SebaroTheme.typography.code,
                color = c.text,
                modifier = Modifier.padding(bottom = t.space.s2),
            )
        }
    }
}

/**
 * A failed action's sentence and details, the action and [after] (a hint, a secondary action) in one scrolling area
 * (CHECKS.md §85, §87; provisional, agent). When a bounded height does not hold them all, the action stays pinned to the
 * area's end, the sentence has all the rest, and scrolling on brings the action to its own place with [after] under it.
 * So the action shows, the order stays, and every word is reachable. A mark shows that the area scrolls. Under an unbounded
 * height (an app's scrolling parent) all of it simply stands. [action] and [after] keep their place in the composition,
 * so the action keeps its focus between the states. A new failure starts at its sentence, a turned window keeps its place,
 * and the order, the Up key and TalkBack's step do not depend on where the pinned action lies (CHECKS.md §88).
 */
@Composable
internal fun SbFailedOverAction(state: SbActionState, modifier: Modifier, action: @Composable () -> Unit, hint: @Composable () -> Unit, after: @Composable () -> Unit) {
    val t = SebaroTheme.tokens
    val c = SebaroTheme.colors
    val failed = state is SbActionState.Failed
    // keyed: the place belongs to one failure, so scrolling on and failing again cannot start past the sentence. Counted
    // and saved, so a window rebuilt in the same form keeps its place as far as its new height lets it (a camera that turns
    // has another form, and starts anew), and a sentence that comes back after a restored other state does not
    val reason = (state as? SbActionState.Failed)?.reason
    val attempt = (state as? SbActionState.Failed)?.attempt ?: 0
    var lastReason by rememberSaveable { mutableStateOf<String?>(null) }
    var lastAttempt by rememberSaveable { mutableStateOf(0) }
    var failure by rememberSaveable { mutableStateOf(0) }
    if (reason != lastReason || attempt != lastAttempt) {
        lastReason = reason
        lastAttempt = attempt
        if (reason != null) failure += 1
    }
    // a failure's place is not the resting bar's: the bar after it opens at its action (CHECKS.md §96)
    val scroll = sbKeyed(if (failed) failure else 0) { rememberScrollState() }
    // what a busy bar too tall for its window leaves above: its end shows, with the way to cancel (CHECKS.md §89)
    val busyHidden = remember { mutableIntStateOf(0) }
    val pinned = remember { mutableIntStateOf(0) }
    val floor = LocalSbContentFloor.current
    val sentenceTall = remember { mutableIntStateOf(0) }
    LaunchedEffect(floor, pinned.intValue, sentenceTall.intValue) {
        floor?.action = pinned.intValue
        floor?.sentence = sentenceTall.intValue
    }
    val hintStyleLine = with(LocalDensity.current) { SebaroTheme.typography.caption.lineHeight.toDp() }
    // a resting bar too tall for its window scrolls, with what stands under the action (CHECKS.md §95). Only then
    var restCut by remember { mutableStateOf(false) }
    val details = remember { FocusRequester() }
    val scope = rememberCoroutineScope()
    // room for the focus ring inside the area: verticalScroll clips, and the last part stands flush at its end. So a
    // pinned action covers its height and that room on both sides
    val ring = with(LocalDensity.current) { 4.dp.roundToPx() }
    val band = if (failed) ring.toFloat() else 0f
    // how many px of the words lie under a pinned action; the fade stands above it, and past it at the area's end
    val wordsTall = remember { mutableIntStateOf(0) }
    val wordsCovered = { wordsTall.intValue - (scroll.value + scroll.viewportSize - pinned.intValue - ring) }
    val line = with(LocalDensity.current) { t.size.targetTouch.toPx() }
    // TalkBack's step is the whole area, so what the action covers would pass unseen. On both sides of verticalScroll:
    // which of two such actions counts is not the same in every Compose version
    val talkStep = Modifier.semantics {
        sbTalkScrollBy { _, y ->
            val free = abs(y) - pinned.intValue - 2 * ring
            // no further than the free room shows, or words pass unseen; next to no room gives the arrow's step
            val by = if (free >= line / 4) free else minOf(line, abs(y))
            scope.launch { scroll.scrollBy(if (y > 0f) by else -by) }
            if (y > 0f) scroll.canScrollForward else scroll.canScrollBackward
        }
    }
    Layout(
        content = {
            if (state is SbActionState.Failed) {
                Column(Modifier.fillMaxWidth().semantics {
                    isTraversalGroup = true
                    traversalIndex = 0f
                }) {
                    Row(
                        Modifier
                            .fillMaxWidth()
                            .padding(bottom = t.space.s2)
                            .onSizeChanged { sentenceTall.intValue = it.height }
                            .semantics { liveRegion = LiveRegionMode.Polite },
                        horizontalArrangement = Arrangement.spacedBy(t.space.s1),
                    ) {
                        Icon(
                            SebaroIcons.Outline16.Error,
                            contentDescription = null,
                            tint = c.danger,
                            modifier = Modifier.padding(top = t.space.s0_5).size(t.size.iconSm),
                        )
                        SbWrapText(state.reason, SebaroTheme.typography.body, c.text)
                    }
                    if (state.details != null) {
                        SbErrorDetailsView(
                            state.details,
                            Modifier
                                .fillMaxWidth()
                                .padding(start = t.size.iconSm + t.space.s1, bottom = t.space.s2),
                            false,
                            pinned.intValue + 2 * ring,
                            scroll.viewportSize,
                            details,
                        )
                    }
                }
            }
            Column(
                Modifier
                    .fillMaxWidth()
                    .onSizeChanged { pinned.intValue = it.height }
                    // over the ring's room as well, or words show around a pinned action's ring
                    .drawBehind { drawRect(c.bg, Offset(0f, -band), Size(size.width, size.height + 2 * band)) }
                    // at the area's start the details lie under the action, and the search upward would pass them
                    .focusProperties { if (state is SbActionState.Failed && state.details != null) up = details }
                    .then(if (failed) Modifier.semantics {
                        isTraversalGroup = true
                        traversalIndex = 1f
                    } else Modifier),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) { action() }
            Column(
                Modifier.fillMaxWidth().then(if (failed) Modifier.semantics {
                    isTraversalGroup = true
                    traversalIndex = 2f
                } else Modifier),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) { hint() }
            Column(
                Modifier.fillMaxWidth().then(if (failed) Modifier.semantics {
                    isTraversalGroup = true
                    traversalIndex = 3f
                } else Modifier),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) { after() }
        },
        // only a failed bar scrolls: another state keeps no focus stop and no scrolling node
        modifier = modifier.then(
            if (failed) {
                Modifier
                    .semantics { isTraversalGroup = true }
                    .sbScrollMark(
                        scroll,
                        c.borderStrong,
                        outside = t.space.s2,
                        fadeEnd = { if (wordsCovered() > 0) size.height - pinned.intValue - ring else size.height },
                        unseen = { wordsCovered().let { if (it > 0) it else scroll.maxValue - scroll.value } },
                        // the action in its own place, with the hint under it still coming: the fade only below it and its ring
                        fadeFrom = { if (wordsCovered() > 0) 0f else (wordsTall.intValue + pinned.intValue + ring - scroll.value).toFloat() },
                    )
                    .layout { measurable, constraints ->
                        // verticalScroll takes no unbounded height; this one is never reached, so all of it stands
                        val most = if (constraints.hasBoundedHeight) constraints.maxHeight + ring else SB_UNBOUNDED_AREA
                        val p = measurable.measure(constraints.copy(maxHeight = most))
                        // the ring's room lies past the area's own end, in the bar's padding, so the bar keeps its height
                        layout(p.width, p.height - ring) { p.placeRelative(0, 0) }
                    }
                    .sbScrollKeys(scroll) { if (scroll.maxValue > 0) pinned.intValue + 2 * ring else 0 }
                    .then(talkStep)
                    .verticalScroll(scroll)
                    .then(talkStep)
            } else if (restCut && state !is SbActionState.Busy) {
                // an action and keys under it, so no fade. The ring's room inside, or the scroller's clip would cut it
                Modifier
                    .sbScrollMark(scroll, c.borderStrong, outside = t.space.s2, fade = false)
                    .sbScrollKeys(scroll)
                    .verticalScroll(scroll)
                    .padding(vertical = t.space.s1)
            } else {
                // only the top is cut: a ring reaches past the sides and the end. By a layer, which cuts the touches as well:
                // what lies above the bar's top would take a tap meant for the head (CHECKS.md §94)
                if (busyHidden.intValue > 0) Modifier.graphicsLayer { clip = true; shape = SbTopCutShape } else Modifier
            },
        ),
    ) { measurables, constraints ->
        val free = constraints.copy(minHeight = 0)
        val words = measurables.dropLast(3).map { it.measure(free) }
        val button = measurables[measurables.size - 3].measure(free)
        val busyBar = state is SbActionState.Busy && constraints.hasBoundedHeight
        // a busy bar's end is its way to cancel: it stands, also past the height
        val rest = measurables.last().measure(if (busyBar) free.copy(maxHeight = Constraints.Infinity) else free)
        val wordsHeight = words.sumOf { it.height }
        // the hint gives way first, by whole lines, before the word in the action (CHECKS.md §95)
        val hintGap = t.space.s2.roundToPx()
        val hintRoom = constraints.maxHeight - wordsHeight - button.height - rest.height - hintGap
        val hintLine = hintStyleLine.roundToPx().coerceAtLeast(1)
        val note = measurables[measurables.size - 2].measure(
            if (busyBar) free.copy(maxHeight = if (hintRoom < hintLine) 0 else hintRoom / hintLine * hintLine + hintGap) else free,
        )
        wordsTall.intValue = wordsHeight
        val room = if (failed) ring else 0
        val under = note.height + rest.height
        val whole = wordsHeight + button.height + under + room
        // within the constraints: another state over its height scrolls, and a busy one shows its end
        val hidden = if (busyBar) (whole - constraints.maxHeight).coerceAtLeast(0) else 0
        busyHidden.intValue = hidden
        restCut = !failed && state !is SbActionState.Busy &&
            // past the scroller's own padding, or that alone would hold the form
            (restCut && scroll.maxValue > t.space.s2.roundToPx() || constraints.hasBoundedHeight && whole > constraints.maxHeight)
        layout(button.width, constraints.constrainHeight(whole)) {
            words.forEach { it.placeRelative(0, 0) }
            // read here, so scrolling only places it again; placed in reading order, and it can only lie over the words
            val end = scroll.value + scroll.viewportSize - button.height - room
            button.placeRelative(0, minOf(wordsHeight, end.coerceAtLeast(scroll.value)) - hidden)
            note.placeRelative(0, wordsHeight + button.height - hidden)
            rest.placeRelative(0, wordsHeight + button.height + note.height - hidden)
        }
    }
}

private object SbTopCutShape : Shape {
    override fun createOutline(size: Size, layoutDirection: LayoutDirection, density: Density): Outline =
        Outline.Rectangle(Rect(-size.width, 0f, 2 * size.width, 2 * size.height))
}

/** The height for an area in an unbounded parent: past any text, and it fits Constraints beside any width. */
private const val SB_UNBOUNDED_AREA = 32_000
